skins.css:
/* 极光玻璃 —— 每条规则都带皮肤作用域前缀（sanitizer 强制，整份拒收违规 CSS）。
 * 分工约定（文档第 8 节）：CSS 层管结构/装饰，token 层管颜色变量。
 * data:image/svg+xml;base64, 占位由 index.ts 在 activate 时替换为构建期资产（dev 路径 / build dataURI）。
 */

[data-bp-skin-active="builtin.skin-aurora"] {
  --bp-aurora-glow-opacity: 0.6;
  --bp-aurora-grad-a: rgba(45, 212, 191, var(--bp-aurora-glow-opacity));
  --bp-aurora-grad-b: rgba(56, 189, 248, calc(var(--bp-aurora-glow-opacity) * 0.75));
}

/* 画布区底色：双向极光渐变 + 右上角辉光资产（配置关闭辉光时第三层被规则 3 移除） */
[data-bp-skin-active="builtin.skin-aurora"] #root {
  background-image:
    radial-gradient(ellipse 70% 55% at 15% -5%, var(--bp-aurora-grad-a), transparent 70%),
    radial-gradient(ellipse 55% 45% at 105% 105%, var(--bp-aurora-grad-b), transparent 70%),
    url('data:image/svg+xml;base64,');
  background-repeat: no-repeat;
  background-size: 100% 100%, 100% 100%, 42% auto;
  background-position: top left, bottom right, top right;
}

/* 「显示辉光」= off：仅保留基础渐变（配置投影属性由皮肤自管） */
[data-bp-skin-active="builtin.skin-aurora"][data-bp-aurora-glow="off"] #root {
  background-image:
    radial-gradient(ellipse 70% 55% at 15% -5%, var(--bp-aurora-grad-a), transparent 70%),
    radial-gradient(ellipse 55% 45% at 105% 105%, var(--bp-aurora-grad-b), transparent 70%);
  background-size: 100% 100%, 100% 100%;
  background-position: top left, bottom right;
}
